import{_ as a,o as e,c as r,ag as d}from"./chunks/framework.DMXcdKmJ.js";const u=JSON.parse('{"title":"使用 AI 助手开发工程","description":"在应用开发中配置模型、提出任务、引用工程文件，并检查 AI 修改和开发预览结果。","frontmatter":{"title":"使用 AI 助手开发工程","description":"在应用开发中配置模型、提出任务、引用工程文件，并检查 AI 修改和开发预览结果。","status":"reviewed","kind":"how-to"},"headers":[],"relativePath":"zh/guide/ai-development.md","filePath":"zh/使用指南/使用AI助手开发工程.md"}'),o={name:"zh/guide/ai-development.md"};function i(l,t,n,h,s,c){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="使用-ai-助手开发工程" tabindex="-1">使用 AI 助手开发工程 <a class="header-anchor" href="#使用-ai-助手开发工程" aria-label="Permalink to &quot;使用 AI 助手开发工程&quot;">​</a></h1><p>AI 助手不只回答问题，也能按工具权限读取和修改工程文件、执行开发命令。先从一个小任务开始，自己检查结果，再逐步扩展。</p><p>从“工程管理”打开目标工程的 <strong>“应用开发”</strong>，完成首次模板初始化，并等待开发环境就绪。InduFrame AI 助手位于工作区左侧；区域收起时先展开。无需在自己的电脑另装 AI 界面或另开服务端口。</p><h2 id="_1-先选好模型" tabindex="-1">1. 先选好模型 <a class="header-anchor" href="#_1-先选好模型" aria-label="Permalink to &quot;1. 先选好模型&quot;">​</a></h2><p>输入区域会显示当前模型。没有可用模型或提示“尚未配置模型凭据”时，点击 <strong>“打开工程模型配置”</strong>，按<a href="/induframe-docs/zh/guide/ai-models.html">配置工程 AI 模型</a>处理。</p><p>同一工程的模型配置和凭据由工程成员共享，不是个人独享的密钥保险箱。不要把 API Key、平台密码或现场设备凭据粘贴到聊天里。</p><h2 id="_2-给出一个具体的小任务" tabindex="-1">2. 给出一个具体的小任务 <a class="header-anchor" href="#_2-给出一个具体的小任务" aria-label="Permalink to &quot;2. 给出一个具体的小任务&quot;">​</a></h2><p>说明目标、范围、要使用的数据和不要改动的部分。先讨论方案时，可在“更改工具预设”中选择 <strong><code>chat-only</code>（仅聊天）</strong>；需要读取代码时，再使用适合的工具配置。</p><p>例如：</p><blockquote><p>我想给当前工程增加一个设备概览页面。<br> 先说明需要查看哪些文件和已存在的数据点，等我确认后再修改。<br> 保留现有登录和其他页面，不新建或修改工业采集连接。<br> 请使用现有工程的技术栈，不编造数据点路径。<br> 完成后说明改了什么、怎样查看，以及哪些地方还没有验证。</p></blockquote><p>一次不要混入很多无关改造。需求不确定时，先让助手解释可选方案，再明确本次选择。</p><p>输入完成后点击 <strong>“发送”</strong>，等待回复或工具执行结果。AI 描述“已完成”不代表浏览器画面与实际业务已经核对。</p><h2 id="_3-提供文件和工程资料" tabindex="-1">3. 提供文件和工程资料 <a class="header-anchor" href="#_3-提供文件和工程资料" aria-label="Permalink to &quot;3. 提供文件和工程资料&quot;">​</a></h2><ul><li>输入 <strong><code>@</code></strong> 可查找并引用工程文件，避免只说“修改那个页面”。</li><li>输入 <strong><code>/</code></strong> 可查看当前可用的命令和技能，不必照抄其他环境的命令。</li><li>使用“附加文件”或拖入文件前，先确认不含密码、个人资料或其他不应交给模型的数据；模型能否理解图片还取决于所选模型。</li><li>工程上传资源与聊天附件是不同用途；页面要使用工程资源时，按<a href="/induframe-docs/zh/guide/project-files.html">工程文件说明</a>处理。</li></ul><p>工作区底部的 **“工程上下文”**提供数据点、角色、报警、计算和资源的摘要。修改相关配置后，可点击 <strong>“同步工程上下文”</strong>，等待同步结果，再请 AI 读取最新资料。</p><p>缺少上下文或同步失败时，先处理提示，不让 AI 猜测来源、数据点路径或类型。数据已保存但同步失败时，先重新同步和核对，不重复创建同一份配置。</p><h2 id="_4-理解工具范围" tabindex="-1">4. 理解工具范围 <a class="header-anchor" href="#_4-理解工具范围" aria-label="Permalink to &quot;4. 理解工具范围&quot;">​</a></h2><p>输入框旁的“更改工具预设”提供 <code>chat-only</code>、<code>read-only</code>、<code>default</code>、<code>full</code> 等选择。</p><table tabindex="0"><thead><tr><th>选择</th><th>使用时要知道</th></tr></thead><tbody><tr><td>chat-only</td><td>仅讨论，不执行工具，适合先确认需求</td></tr><tr><td>read-only</td><td>使用只读内置代码工具查看资料；仍需留意平台工具与账号权限，不把预设当成完整安全隔离</td></tr><tr><td>default、full</td><td>包含修改文件和执行命令的内置工具，只在理解任务范围后使用</td></tr></tbody></table><p>工程文件由同工程成员共同使用。AI 的文件修改不是只存在于这段对话中的个人草稿，多人同时改同一文件前应先协调。</p><p>平台还提供当前工程的数据资料与建模能力，具体操作受账号和工具范围限制。<strong>工业采集连接、变量和数据点配置在 AI 接入中只读</strong>，应在<a href="/induframe-docs/zh/guide/industrial-connections.html">工业采集界面</a>配置；AI 可以利用已同步的数据点辅助开发页面、计算和报警。不要因为助手能描述一项配置，就认定它能写入或已实际执行。</p><h2 id="_5-运行中怎样补充或停止" tabindex="-1">5. 运行中怎样补充或停止 <a class="header-anchor" href="#_5-运行中怎样补充或停止" aria-label="Permalink to &quot;5. 运行中怎样补充或停止&quot;">​</a></h2><p>运行期间可用 **“引导”**补充要求，或用 **“后续消息”**安排任务结束后再处理的内容。“引导”不是立即强制中断正在执行的工具。</p><p>需要中止时点击 <strong>“停止”</strong>，再核对当前文件和工具结果。<strong>停止不会自动撤销已经完成的修改或操作</strong>；不要只看到停止按钮就认为工程回到了原样。</p><p>长对话需要整理时，可使用 <strong>“压缩上下文”</strong>。压缩保留摘要，不等于保存工程备份；关键信息、目标与未完成事项应再核对一次。</p><h2 id="_6-检查修改-而不只看回复" tabindex="-1">6. 检查修改，而不只看回复 <a class="header-anchor" href="#_6-检查修改-而不只看回复" aria-label="Permalink to &quot;6. 检查修改，而不只看回复&quot;">​</a></h2><p>AI 创建了 SQL、数据点、计算或报警时，按<a href="/induframe-docs/zh/guide/ai-data-review.html">核对 AI 创建的数据配置</a>回到真实模块检查；不要只在源码文件或聊天记录里找。SQL 数据点的完整操作见<a href="/induframe-docs/zh/guide/sql-datapoints.html">用 SQL 查询生成数据点</a>。</p><ol><li>查看回复里的 **“改动的文件”**及工具执行结果。</li><li>在“编辑器”核对相关源码；有差异视图时检查修改范围。</li><li>打开“页面”，按<a href="/induframe-docs/zh/guide/preview.html">预览说明</a>检查画面、交互和取数。</li><li>让助手明确说明实际执行过的检查、失败项和未验证内容。</li><li>确认没有带入密钥或误改其他业务，再安排后续发布。</li></ol><p>AI 对话里的文件预览和工程“页面”开发预览也不同。正式运行还需要版本和部署步骤，不会因 AI 回复完成而自动更新。</p><h2 id="_7-继续对话或另起任务" tabindex="-1">7. 继续对话或另起任务 <a class="header-anchor" href="#_7-继续对话或另起任务" aria-label="Permalink to &quot;7. 继续对话或另起任务&quot;">​</a></h2><p>从会话列表选择已有对话可继续讨论；新的独立任务可点击 <strong>“新建”</strong>。对话重命名便于以后查找，但不会重命名工程。</p><p>从较早消息创建新会话，或在当前会话中“从此处编辑”，改变的是对话路径，<strong>不是把工程文件回滚到那一刻</strong>。删除或归档对话也不能代替源码备份或撤销修改。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>提示或现象</th><th>先处理什么</th></tr></thead><tbody><tr><td>AI 服务尚未接入</td><td>确认工程开发环境已就绪，联系管理员检查服务</td></tr><tr><td>尚未配置模型凭据、尚未选择可用模型</td><td>打开工程模型配置，保存凭据并选择可用模型，再重新发送</td></tr><tr><td>无法连接服务</td><td>请管理员核对开发节点网络和模型服务地址</td></tr><tr><td>请求过于频繁、额度不足</td><td>检查服务商额度，稍后重试或选择其他可用模型</td></tr><tr><td>回复了但没改文件</td><td>检查是否为仅聊天、工具范围，以及任务是否只要求讨论</td></tr><tr><td>修改后页面不对</td><td>保留文件差异和具体提示，缩小问题后继续，不反复整页重做</td></tr></tbody></table><h2 id="当前可用范围" tabindex="-1">当前可用范围 <a class="header-anchor" href="#当前可用范围" aria-label="Permalink to &quot;当前可用范围&quot;">​</a></h2><p>InduFrame AI 助手通过当前工程工作区使用，不需要额外安装独立服务。独立终端面板、子代理、插件管理、Git worktree 和原生 MCP 配置入口目前不开放；这不影响助手使用已获准的开发工具。不要自行开放服务端口或修改全局配置来绕过限制。</p><p>需要可复用的任务说明时，继续<a href="/induframe-docs/zh/guide/ai-skills.html">使用工程 AI 技能</a>。</p>',37)])])}const _=a(o,[["render",i]]);export{u as __pageData,_ as default};
